// Loop over input items and add a new field called 'myNewField' to the JSON of each one
try {
  const items = $input.all()

// transformar la informacion para preparar texto para el embedding y guardarlo en textoParaEmbedding
//juego:nombre_juego.Género:genero_del_juego
//cuidado... quitar los espacios en blanco y los tabuladores, enter etc de ese resultado


// Usamos map para transformar cada item individualmente
return items.map(item => {
  const data = item.json;

  const textoParaEmbeddings = `juego:${data.nombre}.genero:${data.genero}.tematica:${data.tematica}.plataforma:${data.plataforma}`
  .replace(/[\n\t\r]/g , '')
  .replace(/\s+/g, '')
  .trim();

  return {
    pagecontent: textoParaEmbeddings,
    metadata: {
      id: data.id,
      nombre: data.nombre,
      genero: data.genero,
      plataforma: data.plataforma,
      precio: data.precio,
      imagen:data.url_imagen
    }
  }
});
} catch (error) {
  console.log("Error", error);
  return {
    pagecontent: "",
    metadata: {
      id: "",
      nombre: "",
      genero: "",
      plataforma: "",
      precio: 0,
      imagen:""
    }
  }
}

